<form class="panel crud-form" method="post" action="<?= url('admin/account') ?>"><?= csrf_field() ?><div class="panel-heading"><h2>Sign-in details</h2></div><div class="form-grid"><div class="field full"><label for="account-email">Email address</label><input id="account-email" type="email" name="email" required autocomplete="username" value="<?= e(field_value($row,'email')) ?>"></div><div class="field full"><label for="current_password">Current password</label><input id="current_password" name="current_password" type="password" required autocomplete="current-password"></div><div class="field"><label for="new_password">New password</label><input id="new_password" name="new_password" type="password" required minlength="12" autocomplete="new-password"><small>At least 12 characters.</small></div><div class="field"><label for="confirm_password">Confirm new password</label><input id="confirm_password" name="confirm_password" type="password" required minlength="12" autocomplete="new-password"></div></div><div class="form-actions"><button class="btn btn-primary">Update account</button></div></form>
